const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={players:[],rounds:null,log:[],revision:0},admin=false,viewer=null,tab='players',busy=false;
async function api(url,data){const res=await fetch(url,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const payload=await res.json();if(!res.ok){if(res.status===401){admin=false;viewer=null;render()}if(res.status===409)await refresh(true);throw Error(payload.error||'Не удалось выполнить запрос')}return payload}
function apply(payload){const sc=$('.wiki-scroll'),sx=sc?.scrollLeft||0,sy=sc?.scrollTop||0;state=payload.state;admin=payload.admin;viewer=payload.viewer||null;render();const next=$('.wiki-scroll');if(next){next.scrollLeft=sx;next.scrollTop=sy}if(activeMatch&&$('#dialog').open&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName))openMatch(...activeMatch)}
async function refresh(force=false){try{const payload=await api('/api/state');if(force||payload.state.revision!==state.revision||payload.admin!==admin||payload.viewer?.login!==viewer?.login)apply(payload)}catch(e){if(force)toast('Нет связи с сервером. Обнови страницу после запуска сервера.')}}
async function mutate(action,data={}){if(busy)return;busy=true;try{const payload=await api('/api/action',{action,...data,revision:state.revision});if(action==='generate')tab='bracket';if(action==='regenerate'||action==='reset')tab='players';apply(payload);toast('Сохранено');return true}catch(e){toast(e.message);return false}finally{busy=false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
const player=id=>state.players.find(p=>p.id===id);const nick=id=>player(id)?.nick||'Соперник ещё не определён';
function roundName(r){const remaining=state.rounds.length-r;return remaining===1?'Финал':remaining===2?'Полуфиналы':remaining===3?'Четвертьфиналы':`1/${2**(remaining-1)} финала`}
function render(){const n=state.players.length,size=n>1?2**Math.ceil(Math.log2(n)):0,done=state.rounds?.flat().filter(m=>m.status==='done').length||0,champ=state.rounds?.at(-1)[0].winner;
$('#app').innerHTML=`<header><a class="brand" href="/" aria-label="Главная"><img src="brand.png" alt=""><div>ТУРНИР ПЕКУСОВ<small>CLASH ROYALE</small></div></a><div class="header-right"><span class="header-note">Первый курс / 1 на 1</span>${viewer?`<span class="account-chip">${admin?'Организатор':esc(nick(viewer.playerId))} · ${esc(viewer.login)}</span><button class="ghost" data-action="logout">Выйти</button>`:'<button class="ghost" data-action="login">Войти</button>'}</div></header><main><div class="heading"><div><div class="eyebrow">CLASH ROYALE · ПЕРВЫЙ КУРС</div><h1>${tab==='bracket'?'Турнирная сетка':tab==='rules'?'Правила турнира':'Участники турнира'}</h1><p>${state.rounds?'Один проигрыш — вылет. Нажми на пару, чтобы открыть матч.':'Заполни заявку. Время начала сообщим в чате.'}</p></div><span class="badge">${champ?'Завершён':state.rounds?'Матчи идут':'Идёт регистрация'}</span></div><div class="stats"><div class="stat"><span>Участников</span><strong>${String(n).padStart(2,'0')}</strong></div><div class="stat"><span>${state.rounds?'Матчей завершено':'Формат'}</span><strong>${state.rounds?`${done} / ${n-1}`:'На вылет'}</strong></div><div class="stat"><span>До финала</span><strong>BO3 <span>до 2 побед</span></strong></div><div class="stat"><span>Финал</span><strong>BO5 <span>до 3 побед</span></strong></div></div>${admin?`<div class="adminbar"><div><strong>Панель организатора</strong><div class="note">${state.rounds?'Нажми на матч, чтобы начать его или внести результат.':`${n} игроков · ${Math.max(0,n-1)} матчей · ${size?size-n:0} проходов без игры`}</div></div><div class="actions">${!state.rounds?'<button data-action="seed">Добавить демо-игроков</button><button class="primary" data-action="generate" '+(n<2?'disabled':'')+'>Создать сетку</button>':`<button data-action="regenerate" ${state.rounds.flat().some(m=>['live','done'].includes(m.status))?'disabled':''}>Вернуть регистрацию</button>`}<button data-action="modes">Режимы рулетки</button><button class="ghost" data-action="password">Сменить пароль</button><button class="ghost danger" data-action="reset">Сбросить турнир</button></div></div>`:''}<nav class="tabs"><button data-tab="players" class="${tab==='players'?'selected':''}">Участники <span class="pill">${n}</span></button><button data-tab="bracket" class="${tab==='bracket'?'selected':''}">Турнирная сетка</button><button data-tab="rules" class="${tab==='rules'?'selected':''}">Регламент</button></nav>${tab==='players'?participants():tab==='bracket'?bracket():rules()}</main><footer><span>ТУРНИР ПЕКУСОВ / CLASH ROYALE</span><span>Неофициальный студенческий турнир · Дата и клан будут объявлены в Telegram</span></footer>`;
}
function participants(){const me=viewer?.role==='participant'?player(viewer.playerId):null;return `<div class="layout"><section class="panel"><div class="paneltop"><h2>Список участников</h2><span class="muted">${state.rounds?'Регистрация закрыта':'Регистрация открыта'}</span></div><div class="list">${state.players.length?state.players.map((p,i)=>`<div class="person ${viewer?.playerId===p.id?'is-me':''}"><div class="avatar">${esc(p.nick.slice(0,2).toUpperCase())}</div><div><strong>${esc(p.nick)}${viewer?.playerId===p.id?' <span class="self-mark">это ты</span>':''}</strong><small>${esc(p.name)} · ${esc(p.tag)}</small></div>${admin?`<span class="account-state ${p.hasAccount?'ready':''}">${p.hasAccount?'аккаунт есть':'без аккаунта'}</span><button class="friend-edit" data-account="${p.id}">Аккаунт</button><button class="friend-edit" data-friend="${p.id}">Дружба</button>`:''}${admin&&!state.rounds?`<button class="remove danger" data-remove="${p.id}" aria-label="Удалить ${esc(p.nick)}">×</button>`:`<span class="number">${String(i+1).padStart(2,'0')}</span>`}</div>`).join(''):'<div class="empty"><h3>Пока никто не записался</h3><p>Создай аккаунт, чтобы попасть в турнир.</p></div>'}</div></section><aside class="panel registration"><img class="poster" src="brand.png" alt="Турнир по Clash Royale среди пекусов"><div class="registration-body">${me?`<span class="eyebrow">ТВОЙ АККАУНТ</span><h2 style="margin-top:10px">${esc(me.nick)}</h2><p>${esc(me.name)} · ${esc(me.tag)}</p><p class="note">Логин: <strong>${esc(viewer.login)}</strong></p><button class="primary full" data-action="profile">Редактировать профиль</button><button class="full" data-action="password">Сменить пароль</button>${state.rounds?'<button class="full" data-tab="bracket">Открыть сетку</button>':''}`:!viewer&&!state.rounds?`<span class="eyebrow">АККАУНТ УЧАСТНИКА</span><h2 style="margin-top:10px">Регистрация</h2><form id="register"><label for="login">Логин</label><input id="login" name="login" maxlength="24" pattern="[A-Za-z0-9_.-]{3,24}" autocomplete="username" required placeholder="Например, ivan_01"><label for="reg-password">Пароль — от 8 символов</label><input id="reg-password" name="password" type="password" minlength="8" maxlength="256" autocomplete="new-password" required><label for="name">Имя или ник из чата</label><input id="name" name="name" maxlength="50" required placeholder="Как тебя зовут"><label for="nick">Ник в Clash Royale</label><input id="nick" name="nick" maxlength="40" required placeholder="Твой игровой ник"><label for="tag">Тег игрока</label><input id="tag" name="tag" maxlength="20" required placeholder="#ABC123" autocapitalize="characters"><label for="friendCode">Код дружбы / Player ID</label><input id="friendCode" name="friendCode" maxlength="80" placeholder="Код из игрового профиля"><label for="friendLink">Или ссылка приглашения в друзья</label><input id="friendLink" name="friendLink" type="url" maxlength="1000" placeholder="https://link.clashroyale.com/…"><p class="note">После регистрации ты сразу войдёшь в аккаунт. Код или ссылка будут видны сопернику.</p><div class="error" id="form-error"></div><button class="primary full">Создать аккаунт и записаться</button></form><button class="full" data-action="login">У меня уже есть аккаунт</button>`:!viewer?`<span class="eyebrow">РЕГИСТРАЦИЯ ЗАКРЫТА</span><h2 style="margin-top:12px">Уже участвуешь?</h2><p>Войди, чтобы открыть свой профиль.</p><button class="primary full" data-action="login">Войти в аккаунт</button><button class="full" data-tab="bracket">Открыть сетку</button>`:`<span class="eyebrow">ОРГАНИЗАТОР</span><h2 style="margin-top:12px">Управление турниром</h2><p>Аккаунт: <strong>${esc(viewer.login)}</strong></p><p class="note">Выдавай аккаунты участникам кнопкой «Аккаунт» в списке.</p><button class="full" data-action="password">Сменить свой пароль</button>`}</div></aside></div>`}
function rules(){return '<section class="panel rules"><h2>Формат</h2><p>Сетка на вылет. Серии до двух побед (BO3), финал — до трёх (BO5). Часть игроков при неполной сетке проходит первый раунд без игры.</p><h2>Перед матчем</h2><p>Открой пару в сетке, скопируй код соперника или перейди по его ссылке приглашения. Добавься в друзья и зайди в общий созвон.</p><h2>Режим</h2><p>Организатор нажимает «Начать матч». Рулетка выбирает один режим на всю серию. Карты выбираются в самой игре перед каждым боем.</p><p>В пуле — драфт и тройной драфт. Организатор заранее проверяет доступность в дружеских боях и исключает недоступные варианты. Повторной жеребьёвки у начатого матча нет.</p><h2>Результаты</h2><p>После каждого боя организатор отмечает победителя. По достижении двух побед (трёх в финале) серия завершается автоматически. Счёт и комментарий видны всем.</p><h2>Спорные ситуации</h2><p>Неявки, обрывы связи и переигровки решаем в чате или на созвоне. Организатор может указать техническое поражение и написать причину.</p><h2>Описание режимов</h2><p><a href="https://supercell.com/en/games/clashroyale/blog/news/what-is-draft-challenge/" target="_blank" rel="noopener noreferrer">Драфт — Supercell</a> · <a href="https://supercell.com/en/games/clashroyale/blog/release-notes/the-party-button-update-2/" target="_blank" rel="noopener noreferrer">Тройной драфт — Supercell</a></p></section>'}
function confirmBox(title,body,callback){activeMatch=null;const d=$('#dialog');d.innerHTML=`<button class="close" data-close aria-label="Закрыть">×</button><h2>${title}</h2><p>${body}</p><div class="actions" style="margin-top:22px"><button class="primary" id="confirm">Подтвердить</button><button data-close>Отмена</button></div>`;d.showModal();$('#confirm').onclick=()=>{d.close();callback()}}
function login(){activeMatch=null;const d=$('#dialog');d.innerHTML='<button class="close" data-close aria-label="Закрыть">×</button><span class="eyebrow">АККАУНТ ТУРНИРА</span><h2 style="margin-top:16px">Вход</h2><form id="login-form"><label for="login-name">Логин</label><input id="login-name" autocomplete="username" maxlength="24" required autofocus><label for="password">Пароль</label><input id="password" type="password" autocomplete="current-password" required><p class="error" id="login-error"></p><button class="primary full">Войти</button></form>';d.showModal();$('#login-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{apply(await api('/api/login',{login:$('#login-name').value,password:$('#password').value}));d.close()}catch(err){$('#login-error').textContent=err.message;button.disabled=false}}}
function passwordDialog(){activeMatch=null;const d=$('#dialog');d.innerHTML='<button class="close" data-close aria-label="Закрыть">×</button><h2>Сменить пароль</h2><form id="password-form"><label for="current">Текущий пароль</label><input id="current" type="password" autocomplete="current-password" required><label for="new-password">Новый пароль — от 8 символов</label><input id="new-password" type="password" autocomplete="new-password" minlength="8" maxlength="256" required><label for="repeat-password">Повтори новый пароль</label><input id="repeat-password" type="password" autocomplete="new-password" required><p class="error" id="password-error"></p><button class="primary full">Сохранить пароль</button></form>';d.showModal();$('#password-form').onsubmit=async e=>{e.preventDefault();if($('#new-password').value!==$('#repeat-password').value){$('#password-error').textContent='Пароли не совпадают';return}try{apply(await api('/api/password',{current:$('#current').value,password:$('#new-password').value}));d.close();toast('Пароль изменён. Войди с новым паролем.')}catch(err){$('#password-error').textContent=err.message}}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close')){$('#dialog').close();return}if(b.dataset.tab){tab=b.dataset.tab;render();return}if(b.dataset.match){openMatch(...b.dataset.match.split(',').map(Number));return}const a=b.dataset.action;if(a==='login'){login();return}if(a==='logout'){try{apply(await api('/api/logout',{}))}catch(err){toast(err.message)}return}if(a==='profile'){profileDialog();return}if(a==='password'){passwordDialog();return}if(!admin)return;if(b.dataset.account){accountDialog(b.dataset.account);return}if(b.dataset.remove&&!state.rounds){confirmBox('Убрать участника?',esc(nick(b.dataset.remove)),()=>mutate('remove',{id:b.dataset.remove}));return}if(a==='seed')await mutate('seed');if(a==='generate')confirmBox('Создать сетку?',`Участников: ${state.players.length}. Регистрация закроется. До первого матча можно вернуться и изменить список.`,()=>mutate('generate'));if(a==='regenerate')confirmBox('Вернуть регистрацию?','Жеребьёвка будет удалена. Список участников сохранится.',()=>mutate('regenerate'));if(a==='reset')confirmBox('Сбросить турнир?','Все заявки, аккаунты участников и результаты будут удалены с сервера.',()=>mutate('reset'))});
document.addEventListener('submit',async e=>{if(e.target.id!=='register')return;e.preventDefault();const data=new FormData(e.target),button=e.target.querySelector('button');button.disabled=true;try{apply(await api('/api/register',{login:data.get('login'),password:data.get('password'),name:data.get('name'),nick:data.get('nick'),tag:data.get('tag'),friendCode:data.get('friendCode'),friendLink:data.get('friendLink')}));toast('Аккаунт создан, заявка принята')}catch(err){const error=$('#form-error');if(error)error.textContent=err.message;button.disabled=false}});
const MODES={draft:{name:'Драфт',description:'Четыре раза выбери одну карту из пары. Вторую получает соперник. Ещё четыре карты тебе передаст он.',source:'https://supercell.com/en/games/clashroyale/blog/news/what-is-draft-challenge/'},triple:{name:'Тройной драфт',description:'Собери колоду из восьми карт: на каждом шаге выбери одну из трёх. Варианты соперника тоже видны.',source:'https://supercell.com/en/games/clashroyale/blog/release-notes/the-party-button-update-2/'}};
let activeMatch=null,spinTimer=null;const modeName=m=>MODES[m]?.name||'Не выбран';
function safeFriend(value){try{const u=new URL(value);return u.protocol==='https:'&&['link.clashroyale.com','link.supercell.com','id.supercell.com'].includes(u.hostname)&&!u.username&&!u.password&&!u.port?u.href:null}catch{return null}}
function bracket(){if(!state.rounds)return '<section class="empty"><h2>Сетка появится после жеребьёвки</h2><p>Организатор закроет регистрацию и распределит участников.</p></section>';const rounds=state.rounds,H=rounds[0].length*104+52,W=rounds.length*260-24,champ=rounds.at(-1)[0].winner;let lines='';rounds.forEach((round,r)=>{if(r===rounds.length-1)return;round.forEach((m,i)=>{const y=44+(2*i+1)*2**r*52,y2=44+(2*Math.floor(i/2)+1)*2**(r+1)*52,x=r*260+222;lines+=`<path d="M${x} ${y} H${x+18} V${y2} H${(r+1)*260}"/>`})});return `${champ?`<div class="champion">Победитель турнира: <strong>${esc(nick(champ))}</strong></div>`:''}<div class="bracket-caption">Нажми на матч: режим, соперники и результат. <span>BO3 · финал BO5</span></div><div class="wiki-scroll"><div class="wiki-bracket" style="width:${W}px;height:${H}px"><svg class="connections" width="${W}" height="${H}" aria-hidden="true">${lines}</svg>${rounds.map((round,r)=>`<div class="wiki-round" style="left:${r*260}px">${roundName(r)} <small>${r===rounds.length-1?'BO5':'BO3'}</small></div>${round.map((m,i)=>{const top=44+(2*i+1)*2**r*52-36;return `<button class="wiki-match ${m.status}" data-match="${r},${i}" style="left:${r*260}px;top:${top}px" aria-label="Матч ${r+1}.${i+1}: ${esc(nick(m.p[0]))}, ${esc(nick(m.p[1]))}"><span class="wiki-meta"><span>${r+1}.${i+1}</span><span>${m.status==='bye'?'Без игры':m.status==='done'?(m.technical?'Тех. результат':'Завершён'):m.status==='live'?'В игре':'Ожидает'}</span></span>${m.p.map((id,j)=>`<span class="wiki-player ${id&&m.winner===id?'win':id&&m.winner&&m.winner!==id?'loss':''}"><span>${id?esc(nick(id)):m.status==='bye'?'—':'Участник не определён'}</span><b>${m.score?.[j]??(id&&m.winner===id?'✓':'—')}</b></span>`).join('')}</button>`}).join('')}`).join('')}</div></div>${admin&&state.log.length?`<details class="history"><summary>Журнал организатора</summary>${state.log.slice(0,20).map(l=>`<p>${esc(l.time)} · ${esc(l.text)}</p>`).join('')}</details>`:''}`}
function friendCard(id,m,j){const p=player(id);if(!p)return '<section class="opponent"><h3>Участник не определён</h3><p>Ожидаем предыдущий матч.</p></section>';const url=safeFriend(p.friendLink),result=m.winner?(m.winner===id?'Победитель':'Выбыл'):null;return `<section class="opponent ${result?(m.winner===id?'victor':'defeated'):''}"><div class="opponent-title"><h3>${esc(p.nick)}</h3>${result?`<span class="outcome">${result}</span>`:''}</div><p>${esc(p.name)} · ${esc(p.tag)}</p>${p.friendCode?`<label>Код дружбы / Player ID</label><div class="copyline"><code>${esc(p.friendCode)}</code><button data-copy="${esc(p.friendCode)}">Копировать</button></div>`:''}${url?`<a class="friend-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Добавить в друзья ↗</a>`:!p.friendCode?'<p class="note">Данные для дружбы ещё не добавлены. Свяжитесь в общем чате.</p>':''}${m.score?`<strong class="bigscore">${m.score[j]}</strong>`:''}</section>`}
function matchContents(r,i){const m=state.rounds[r][i],locked=Tournament.locked(state.rounds,r,i),ready=m.p.every(Boolean)&&m.status!=='bye',target=r===state.rounds.length-1?3:2,spinning=m.mode&&m.revealAt>Date.now(),wheelModes=m.modePool||['draft','triple'],slice=360/wheelModes.length,selected=Math.max(0,wheelModes.indexOf(m.mode)),spinEnd=1800-(selected*slice+slice/2);return `<button class="close" data-close aria-label="Закрыть">×</button><div class="eyebrow">${roundName(r)} · матч ${r+1}.${i+1} · BO${target*2-1}</div><h2 class="match-heading">${esc(nick(m.p[0]))} — ${esc(nick(m.p[1]))}</h2><div class="opponents">${m.p.map((id,j)=>friendCard(id,m,j)).join('')}</div><section class="match-mode"><label>Режим серии</label>${spinning?`<div class="roulette" aria-label="Круговая жеребьёвка режима"><div class="roulette-pointer" aria-hidden="true"></div><div class="roulette-wheel" style="--slice:${slice}deg;--spin-end:${spinEnd}deg">${wheelModes.map((mode,k)=>`<span style="--label-angle:${k*slice+slice/2}deg">${modeName(mode)}</span>`).join('')}<i aria-hidden="true"></i></div></div><p class="roulette-status">Крутим рулетку…</p>`:m.mode?`<h3 class="mode-result">${modeName(m.mode)}</h3><p>${MODES[m.mode]?.description||''}</p><p class="note">Вся серия — в этом режиме. Колоды выбираются заново перед каждым боем в игре.</p>`:m.status==='bye'?'<p>Проход без матча. Режим не требуется.</p>':'<p>Режим появится, когда организатор начнёт матч.</p>'}</section>${m.note?`<section class="match-note"><label>Комментарий организатора</label><p>${esc(m.note)}</p></section>`:''}${m.games?.length?`<section class="game-history"><h3>Бои серии</h3>${m.games.map((g,k)=>`<div><span>Бой ${k+1}</span><strong>${esc(nick(g.winner))}</strong><span>Победа</span></div>`).join('')}</section>`:''}${admin&&ready&&!locked?`<section class="match-controls"><h3>Организатор</h3>${m.status==='waiting'||(m.status==='live'&&!m.mode)?'<button class="primary" id="start-match">Начать матч · выбрать режим</button>':''}${m.status==='live'&&m.mode&&!spinning?`<p>Кто выиграл следующий бой?</p><div class="actions">${m.p.map((id,j)=>`<button data-game="${j}">Победа ${esc(nick(id))}</button>`).join('')}</div>`:''}${!spinning&&m.status!=='waiting'?`<details><summary>Ввести или исправить итог серии</summary><form id="score-form"><div class="score">${m.p.map((id,j)=>`<div><label for="score${j}">${esc(nick(id))}</label><input id="score${j}" type="number" min="0" max="${target}" required value="${m.score?.[j]??0}"></div>`).join('')}</div><label for="match-note">Описание результата</label><textarea id="match-note" maxlength="500" rows="3" placeholder="Например: переиграли первый бой из-за обрыва связи">${esc(m.note||'')}</textarea><button class="primary full">Сохранить итог</button></form></details>`:''}<details><summary>Техническое поражение</summary><p>Кто проходит дальше?</p>${m.p.map((id,j)=>`<button data-tech="${j}">${esc(nick(id))}</button>`).join('')}</details><form id="note-form"><label for="public-note">Комментарий для участников</label><textarea id="public-note" maxlength="500" rows="2">${esc(m.note||'')}</textarea><button>Сохранить описание</button></form></section>`:admin&&locked?'<p class="note">Следующий матч уже начался. Изменение результата закрыто.</p>':''}`}
function openMatch(r,i){if(!state.rounds?.[r]?.[i])return;activeMatch=[r,i];clearTimeout(spinTimer);const d=$('#dialog');d.classList.add('match-dialog');d.innerHTML=matchContents(r,i);if(!d.open)d.showModal();const m=state.rounds[r][i],target=r===state.rounds.length-1?3:2;if(m.mode&&m.revealAt>Date.now())spinTimer=setTimeout(()=>{if(d.open&&activeMatch?.join()===`${r},${i}`)openMatch(r,i)},m.revealAt-Date.now()+30);if(!admin)return;const go=async(action,data)=>{if(await mutate(action,{r,i,...data}))openMatch(r,i)};if($('#start-match'))$('#start-match').onclick=()=>go('start');d.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>go('game',{winner:Number(b.dataset.game)}));if($('#score-form'))$('#score-form').onsubmit=e=>{e.preventDefault();go('result',{a:Number($('#score0').value),b:Number($('#score1').value),note:$('#match-note').value})};if($('#note-form'))$('#note-form').onsubmit=e=>{e.preventDefault();go('note',{note:$('#public-note').value})};d.querySelectorAll('[data-tech]').forEach(b=>b.onclick=()=>{const j=Number(b.dataset.tech);d.close();confirmBox('Технический результат',`Победа ${esc(nick(m.p[j]))}.`,()=>go('result',{a:j===0?target:0,b:j===1?target:0,technical:true,note:'Техническое поражение соперника'}))})}
function modesDialog(){const d=$('#dialog');d.classList.remove('match-dialog');d.innerHTML=`<button class="close" data-close aria-label="Закрыть">×</button><h2>Режимы рулетки</h2><p>Отметь режимы, доступные в дружеских боях вашего клана. Уже выпавшие режимы сохранятся.</p><form id="modes-form">${Object.entries(MODES).map(([id,m])=>`<label class="check"><input type="checkbox" name="mode" value="${id}" ${(state.modePool||['draft','triple']).includes(id)?'checked':''}>${m.name}</label><p class="note">${m.description} <a href="${m.source}" target="_blank" rel="noopener noreferrer">Правила Supercell</a></p>`).join('')}<button class="primary full">Сохранить</button></form>`;d.showModal();$('#modes-form').onsubmit=async e=>{e.preventDefault();const pool=[...new FormData(e.target).getAll('mode')];if(await mutate('modes',{pool}))d.close()}}
function editFriend(id){const p=player(id),d=$('#dialog');d.classList.remove('match-dialog');d.innerHTML=`<button class="close" data-close aria-label="Закрыть">×</button><h2>${esc(p.nick)}</h2><form id="friend-form"><label for="friend-code">Код дружбы / Player ID</label><input id="friend-code" maxlength="80" value="${esc(p.friendCode||'')}"><label for="friend-link">Ссылка приглашения</label><input id="friend-link" type="url" maxlength="1000" value="${esc(p.friendLink||'')}"><button class="primary full">Сохранить</button></form>`;d.showModal();$('#friend-form').onsubmit=async e=>{e.preventDefault();if(await mutate('friend',{id,friendCode:$('#friend-code').value,friendLink:$('#friend-link').value}))d.close()}}
function profileDialog(){const p=player(viewer?.playerId);if(!p)return;activeMatch=null;const d=$('#dialog');d.classList.remove('match-dialog');d.innerHTML=`<button class="close" data-close aria-label="Закрыть">×</button><span class="eyebrow">ЛИЧНЫЙ ПРОФИЛЬ</span><h2 style="margin-top:14px">Редактировать данные</h2><form id="profile-form"><label for="profile-name">Имя или ник из чата</label><input id="profile-name" maxlength="50" required value="${esc(p.name)}"><label for="profile-nick">Ник в Clash Royale</label><input id="profile-nick" maxlength="40" required value="${esc(p.nick)}"><label for="profile-tag">Тег игрока</label><input id="profile-tag" maxlength="20" required value="${esc(p.tag)}"><label for="profile-code">Код дружбы / Player ID</label><input id="profile-code" maxlength="80" value="${esc(p.friendCode||'')}"><label for="profile-link">Ссылка приглашения</label><input id="profile-link" type="url" maxlength="1000" value="${esc(p.friendLink||'')}"><p class="error" id="profile-error"></p><button class="primary full">Сохранить профиль</button></form>`;d.showModal();$('#profile-form').onsubmit=async e=>{e.preventDefault();try{apply(await api('/api/profile',{name:$('#profile-name').value,nick:$('#profile-nick').value,tag:$('#profile-tag').value,friendCode:$('#profile-code').value,friendLink:$('#profile-link').value}));d.close();toast('Профиль обновлён')}catch(err){$('#profile-error').textContent=err.message}}}
function accountDialog(id){const p=player(id);if(!p)return;activeMatch=null;const d=$('#dialog');d.classList.remove('match-dialog');d.innerHTML=`<button class="close" data-close aria-label="Закрыть">×</button><span class="eyebrow">АККАУНТ УЧАСТНИКА</span><h2 style="margin-top:14px">${esc(p.nick)}</h2><p>${p.hasAccount?'Задайте новый логин и пароль. Текущая сессия участника завершится.':'Создайте данные для входа и передайте их участнику лично.'}</p><form id="account-form"><label for="account-login">Логин</label><input id="account-login" maxlength="24" pattern="[A-Za-z0-9_.-]{3,24}" autocomplete="off" required placeholder="Например, player_01"><label for="account-password">Пароль — от 8 символов</label><input id="account-password" type="password" minlength="8" maxlength="256" autocomplete="new-password" required><p class="error" id="account-error"></p><button class="primary full">${p.hasAccount?'Обновить аккаунт':'Создать аккаунт'}</button></form>`;d.showModal();$('#account-form').onsubmit=async e=>{e.preventDefault();try{apply(await api('/api/accounts/set',{playerId:id,login:$('#account-login').value,password:$('#account-password').value}));d.close();toast('Данные аккаунта сохранены')}catch(err){$('#account-error').textContent=err.message}}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.copy){try{await navigator.clipboard.writeText(b.dataset.copy);toast('Код скопирован')}catch{toast('Не удалось скопировать. Выдели код вручную.')}}if(admin&&b.dataset.action==='modes')modesDialog();if(admin&&b.dataset.friend)editFriend(b.dataset.friend)});
$('#dialog').addEventListener('close',()=>{if(!$('#dialog').open){activeMatch=null;clearTimeout(spinTimer);$('#dialog').classList.remove('match-dialog')}});

$('#app').innerHTML='<main><p>Загружаем турнир…</p></main>';
api('/api/state').then(payload=>{if(payload.state.rounds)tab='bracket';apply(payload)}).catch(()=>{$('#app').innerHTML='<main><h1>Сервер недоступен</h1><p>Запусти сервер турнира и обнови страницу.</p></main>'});
setInterval(()=>{if(!document.hidden&&(!$('#dialog').open||activeMatch)&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName))refresh()},1000);
